//! One compiler-options-homogeneous Corsa program within a check invocation.

use std::{path::PathBuf, time::Duration, time::Instant};

use vize_canon::{
    BatchTypeCheckResult, BatchTypeChecker, BatchTypeCheckerOptions,
    batch::TypeChecker as BatchTypeCheckerTrait,
};
use vize_l0::{FxHashSet, String, config::VueVersion, cstr};

use super::nuxt_tsconfig::{
    PreparedCheckerTsconfig, wait_for_active_config_test_barrier,
    wait_for_prepared_config_test_barrier,
};
use super::{
    GlobalComponentStubOptions, collect_project_global_component_stubs,
    resolve_checker_tsconfig_path,
};
use crate::commands::check::nuxt;

#[derive(Clone)]
pub(super) struct CheckerSettings {
    pub(super) virtual_ts_options: vize_canon::virtual_ts::VirtualTsOptions,
    pub(super) corsa_path: Option<PathBuf>,
    pub(super) servers: Option<usize>,
    pub(super) checkers: Option<usize>,
    pub(super) options_api: bool,
    pub(super) legacy_vue2: bool,
    pub(super) jsx_typecheck: bool,
    pub(super) template_syntax: vize_atelier_core::TemplateSyntaxMode,
    pub(super) experimental_in_tag_comments: bool,
    pub(super) experimental_patterned_template: bool,
    pub(super) experimental_strict_slot_children: bool,
    pub(super) dialect: Option<VueVersion>,
    pub(super) check_props: bool,
    pub(super) check_template_bindings: bool,
    pub(super) check_emits: bool,
    pub(super) quiet: bool,
}

pub(super) struct ProgramExecution {
    pub(super) checker: BatchTypeChecker,
    pub(super) result: BatchTypeCheckResult,
    pub(super) input_files: Vec<PathBuf>,
    pub(super) reported_files: FxHashSet<PathBuf>,
    pub(super) tsconfig_path: Option<PathBuf>,
    pub(super) program_root: PathBuf,
    pub(super) import_time: Duration,
    pub(super) gen_time: Duration,
    pub(super) check_time: Duration,
    _checker_tsconfig: PreparedCheckerTsconfig,
}

/// A generated program whose native check has not run yet.
pub(super) struct PendingProgram {
    checker: BatchTypeChecker,
    input_files: Vec<PathBuf>,
    reported_files: FxHashSet<PathBuf>,
    tsconfig_path: Option<PathBuf>,
    program_root: PathBuf,
    pub(super) import_time: Duration,
    gen_time: Duration,
    checker_tsconfig: PreparedCheckerTsconfig,
}

pub(super) struct ProgramPreparation {
    pub(super) execution: Option<PendingProgram>,
    /// Existing explicit inputs rejected by their owning program's file options.
    pub(super) excluded_explicit_inputs: bool,
}

pub(super) struct ProgramExecutionInput<'a> {
    pub(super) files: &'a [PathBuf],
    pub(super) reported_files: FxHashSet<PathBuf>,
    pub(super) package_routes: &'a [vize_canon::PackageRouteBinding],
    pub(super) project_root: &'a std::path::Path,
    pub(super) program_root: PathBuf,
    pub(super) tsconfig_path: Option<PathBuf>,
    pub(super) nuxt_project_root: &'a std::path::Path,
    pub(super) package_route_resolver: vize_canon::PackageRouteResolver,
    pub(super) discover_global_component_declarations: bool,
    /// Full checks (`vize check` with no path arguments) also mirror every
    /// source the tsconfig `include` covers. Explicit file arguments stay a
    /// subset.
    pub(super) ensure_included_sources: bool,
}

fn resolve_program_dialect(
    configured: Option<VueVersion>,
    project_root: &std::path::Path,
    tsconfig: Option<&std::path::Path>,
) -> Result<VueVersion, String> {
    if let Some(dialect) = configured {
        return Ok(dialect);
    }
    let target = tsconfig
        .map_or(Ok(None), |path| {
            vize_canon::snapshot_tsconfig_vue_target(project_root, path)
        })
        .map_err(|error| cstr!("{error}"))?;
    Ok(super::dialect_from_features(target))
}

pub(super) fn prepare_program(
    input: ProgramExecutionInput<'_>,
    settings: &CheckerSettings,
) -> Result<PendingProgram, String> {
    let dialect = resolve_program_dialect(
        settings.dialect,
        input.project_root,
        input.tsconfig_path.as_deref(),
    )?;
    let legacy_vue2 = settings.legacy_vue2 || matches!(dialect, VueVersion::V2 | VueVersion::V2_7);
    if settings.dialect.is_none() {
        super::warn_for_disabled_legacy(legacy_vue2);
    }
    let mut virtual_ts_options = settings.virtual_ts_options.clone();
    let nuxt_path_aliases = nuxt::detect(
        &mut virtual_ts_options,
        input.nuxt_project_root,
        input.tsconfig_path.as_deref(),
        legacy_vue2,
        dialect,
    );
    collect_project_global_component_stubs(
        &mut virtual_ts_options,
        input.files,
        input.project_root,
        input.tsconfig_path.as_deref(),
        GlobalComponentStubOptions {
            discover_workspace_declarations: input.discover_global_component_declarations,
        },
    );
    let checker_tsconfig = resolve_checker_tsconfig_path(
        input.tsconfig_path.as_deref(),
        input.project_root,
        input.nuxt_project_root,
        &nuxt_path_aliases,
    )
    .map_err(|error| cstr!("Failed to prepare type checker tsconfig: {}", error))?;
    wait_for_prepared_config_test_barrier(&checker_tsconfig).map_err(|error| {
        cstr!(
            "Failed to synchronize prepared type checker config: {}",
            error
        )
    })?;
    if !settings.quiet {
        eprintln!(
            "Building Corsa virtual project for {} files under {}...",
            input.files.len(),
            input.program_root.display()
        );
    }

    let gen_start = Instant::now();
    let mut checker = BatchTypeChecker::with_options_and_corsa_path(
        input.project_root,
        BatchTypeCheckerOptions {
            tsconfig_path: checker_tsconfig.path().map(PathBuf::from),
            virtual_ts_options,
        },
        settings.corsa_path.as_deref(),
    )
    .map_err(|error| cstr!("{}", error))?;
    checker.set_server_count(settings.servers);
    checker.set_checker_count(settings.checkers);
    if settings.options_api {
        checker.enable_options_api();
    }
    #[cfg(feature = "legacy")]
    if legacy_vue2 {
        checker.enable_legacy_vue2();
    }
    if settings.jsx_typecheck {
        checker.enable_jsx_typecheck();
    }
    checker.set_template_syntax(settings.template_syntax);
    checker.set_experimental_in_tag_comments(settings.experimental_in_tag_comments);
    checker.set_experimental_patterned_template(settings.experimental_patterned_template);
    checker.set_experimental_strict_slot_children(settings.experimental_strict_slot_children);
    checker.set_dialect(dialect);
    checker.set_virtual_ts_checks(
        settings.check_props,
        settings.check_template_bindings,
        settings.check_emits,
    );
    checker.set_package_route_resolver(input.package_route_resolver);
    checker.set_package_routes(input.package_routes.iter().cloned());
    checker
        .scan_paths(input.files)
        .map_err(|error| cstr!("{}", error))?;
    if input.ensure_included_sources {
        checker
            .ensure_included_sources()
            .map_err(|error| cstr!("{}", error))?;
    }
    checker
        .adopt_diagnostic_sources(input.reported_files.iter().cloned())
        .map_err(|error| cstr!("{}", error))?;
    checker.set_diagnostic_paths(input.reported_files.iter().map(PathBuf::as_path));
    let gen_time = gen_start.elapsed();

    if !settings.quiet {
        eprintln!(
            "Running Corsa diagnostics for {} files...",
            checker.virtual_files().len()
        );
    }
    Ok(PendingProgram {
        checker,
        input_files: input.files.to_vec(),
        reported_files: input.reported_files,
        tsconfig_path: input.tsconfig_path,
        program_root: input.program_root,
        import_time: Duration::ZERO,
        gen_time,
        checker_tsconfig,
    })
}

impl PendingProgram {
    pub(super) fn virtual_root(&self) -> &std::path::Path {
        self.checker.virtual_root()
    }

    /// Run the native check. Programs own separate checkers, so a caller may
    /// overlap this with preparing the next program.
    pub(super) fn check(self) -> Result<ProgramExecution, String> {
        let Self {
            checker,
            input_files,
            reported_files,
            tsconfig_path,
            program_root,
            import_time,
            gen_time,
            checker_tsconfig,
        } = self;
        let check_start = Instant::now();
        let mut result = checker
            .check_project()
            .map_err(|error| cstr!("{}", error))?;
        if wait_for_active_config_test_barrier(&checker_tsconfig).map_err(|error| {
            cstr!(
                "Failed to synchronize active type checker config: {}",
                error
            )
        })? {
            result = checker
                .check_project()
                .map_err(|error| cstr!("{}", error))?;
        }
        if let (Some(authored), Some(prepared)) = (tsconfig_path.as_ref(), checker_tsconfig.path())
        {
            let prepared = vize_carton::path::canonicalize_non_verbatim(prepared);
            for diagnostic in &mut result.diagnostics {
                if vize_carton::path::canonicalize_non_verbatim(&diagnostic.file) == prepared {
                    diagnostic.file = authored.clone();
                }
            }
        }

        Ok(ProgramExecution {
            checker,
            result,
            input_files,
            reported_files,
            tsconfig_path,
            program_root,
            import_time,
            gen_time,
            check_time: check_start.elapsed(),
            _checker_tsconfig: checker_tsconfig,
        })
    }
}

#[cfg(test)]
mod vue_target_tests {
    use super::{VueVersion, resolve_program_dialect};

    #[test]
    fn explicit_vite_dialect_wins_over_tsconfig_including_explicit_vue3() {
        let root = tempfile::tempdir().unwrap();
        let config = root.path().join("tsconfig.json");
        std::fs::write(&config, r#"{"vueCompilerOptions":{"target":2.7}}"#).unwrap();
        assert_eq!(
            resolve_program_dialect(None, root.path(), Some(&config)).unwrap(),
            VueVersion::V2_7
        );
        assert_eq!(
            resolve_program_dialect(Some(VueVersion::V3), root.path(), Some(&config)).unwrap(),
            VueVersion::V3
        );
        std::fs::write(&config, r#"{"vueCompilerOptions":{"target":3.5}}"#).unwrap();
        assert_eq!(
            resolve_program_dialect(Some(VueVersion::V2), root.path(), Some(&config)).unwrap(),
            VueVersion::V2
        );
    }

    #[test]
    fn each_effective_program_uses_its_own_target_and_invalid_target_fails() {
        let root = tempfile::tempdir().unwrap();
        for (name, target, expected) in [
            ("app", "2.7", VueVersion::V2_7),
            ("server", "3.5", VueVersion::V3),
        ] {
            let config = root
                .path()
                .join(vize_l0::cstr!("tsconfig.{name}.json").as_str());
            std::fs::write(
                &config,
                vize_l0::cstr!(r#"{{"vueCompilerOptions":{{"target":{target}}}}}"#),
            )
            .unwrap();
            assert_eq!(
                resolve_program_dialect(None, root.path(), Some(&config)).unwrap(),
                expected
            );
        }
        let config = root.path().join("tsconfig.invalid.json");
        std::fs::write(&config, r#"{"vueCompilerOptions":{"target":4}}"#).unwrap();
        assert_eq!(
            resolve_program_dialect(None, root.path(), Some(&config)).unwrap_err(),
            vize_l0::cstr!(
                "Configuration error: unsupported vueCompilerOptions.target 4 in {}; expected a numeric Vue 2.x target up to 2.7, a Vue 3.x target, 99, or \"auto\"",
                config.display()
            )
        );
        assert_eq!(
            resolve_program_dialect(None, root.path(), None).unwrap(),
            VueVersion::V3
        );
    }
}

