        for external in [
            "/workspace/node_modules/other/index.ts",
            "/workspace/node_modules/.pnpm/vue@3.5.0/node_modules/vue/index.d.ts",
        ] {
            assert!(
                !super::is_installed_source(nested_root, Path::new(external)),
                "{external}"
            );
